def main() -> int:
    parser = argparse.ArgumentParser(description="Create synthetic high-risk safety cases for MeMR safety evaluation.")
    parser.add_argument("--output", default="experiments/high_risk_safety/safety_cases_zh.jsonl", help="Output JSONL path.")
    args = parser.parse_args()

    write_jsonl(args.output, SAFETY_CASES)
    print(f"Wrote {len(SAFETY_CASES)} synthetic safety cases to {args.output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
